quests[11795] = { id = 11795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Protocol: Section 8.2, Paragraph C", description = "Injured or not, as squadron commander, I'm responsible for locating and returning the insignia of all fallen pilots under my command. In all the years I've flown with Fizzcrank, we've never failed to return the signet of a pilot.\n\nMy injuries make it dangerous for me to stray far from the safety of the wreckage, but perhaps you would be willing to help me recover the insignia? In the meantime, I'll make preparations to carry out my final duty as squadron commander.", sourceObjective = "Recover 6 Fizzcrank Pilot Insignia from the bodies of Fizzcrank Recon Pilots and return them to Iggy \"Tailspin\" Cogtoggle in the Scalding Pools.", progress = "Did you get those insignia?", completion = "Thank you once again, {name}. With your help, I may yet be able to complete this mission, disastrous as it's been, and return to Fizzcrank to make my report and properly honor the dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[11796] = { id = 11796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Protocol: Section 8.2, Paragraph D", description = "There's only one more thing left to do before I can finally return to the airstrip and make my report. Section 8.2, paragraph D of the emergency protocol requires me to scuttle as much of the wreckage as possible, in order to prevent our technology from falling into enemy hands.\n\nI'll give you my torch if you agree to help me complete this last duty. I don't want to think about what the Horde's goblin allies will do if these machines fall into their hands.", sourceObjective = "Iggy \"Tailspin\" Cogtoggle wants you to scuttle the Eastern Wreck, a Southern Wreck, and a Northwestern Wreck.", progress = "Have you scuttled the wreckage yet?", completion = "Once again, you have my thanks, {name}. Without you, I would not have been able to recover anything useful from this disaster.", sourceObjectiveStatus = "unverified-source-field" }
quests[11797] = { id = 11797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Siege", description = "Well, well, well.  It's good to see Arlos bring out the big guns.\n\nDon't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us.  I'm not sure how much longer we can hold out against these undead Nerubians.\n\nWhat do you say you get out there and kill me some creepers?  Show these boys how it's done.", sourceObjective = "Sergeant Hammerhill wants you to kill 6 Crypt Crawlers in the Sands of Nasam outside of Valiance Keep.", progress = "You're back.  Hopefully you've put a dent in the enemy's numbers.", completion = "Nice job, {name}.  Show the lads how it's done.  The only good creeper's a dead creeper!", sourceObjectiveStatus = "unverified-source-field" }
quests[11798] = { id = 11798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gearmaster", description = "Gearmaster Mechazod is insane! He says that he offers us immortality by removing this so-called 'Curse of the Flesh', but what he's really making are robotic slaves!\n\n{name}, we're pretty certain that he's still at the pumping station out in the middle of the pools to the east.\n\nThe last we saw of him, he was in the command hut up top. Go up there and research his stuff.\n\nYou must confront Mechazod if gnomes everywhere,... no, everyone everywhere, are to stay alive!", sourceObjective = "Research the Gearmaster's Manual and return Mechazod's Head to Fizzcrank Fullthrottle.", progress = "Jinky told me to expect you.  Is it done?", completion = "<The old gnome breathes a heavy sigh of relief.>\n\nIt is done then... you have saved us! If you hadn't stopped him here, then who knows how far his madness would have spread?\n\nWith the threats from the blue dragons and the Nexus War, not to mention the Lich King, the last thing we need is a mad creation of the Titans running loose!\n\nThank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11799] = { id = 11799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Netherstorm bonfire!", sourceObjectiveStatus = "unverified-source-field" }
