quests[11863] = { id = 11863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Zangarmarsh flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11864] = { id = 11864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mission Statement", sourceObjective = "The demon has many names and each name has held special meaning at one time or another. While the details were sometimes insignificant, the end result was always the same: death.\n\nBut it is now, nearly fifty years after it all began, that the details will find the devil and lead to his downfall.\n\nThis time, we have him... There will be no escape for Nesingwary.\n\nNorthrend will be the battleground for our war. The hunter will become the hunted!", sourceObjectiveStatus = "unverified-source-field" }
quests[11865] = { id = 11865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfit for Death", description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!\n\nTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!", sourceObjective = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.", progress = "Feel no pity for them, {race}.", completion = "You do the Earth Mother's work, {name}, but do not revel in this victory for too long. We have discovered the hiding place of the trapper leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[11866] = { id = 11866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of Our Enemies", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Ears will do quite nicely...", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", sourceObjectiveStatus = "unverified-source-field" }
quests[11867] = { id = 11867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Get Ear-nough...", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nessingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!", sourceObjectiveStatus = "unverified-source-field" }
quests[11868] = { id = 11868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Culler Cometh", description = "Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare yourself properly, {name}. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!", sourceObjective = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.", progress = "Nature demands justice!", completion = "Perhaps her death will serve as an example to others that dare slay animals for sport and riches.", sourceObjectiveStatus = "unverified-source-field" }
quests[11869] = { id = 11869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Happy as a Clam", description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!", sourceObjective = "Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.", progress = "It is gruesome work that we do, {name}.", completion = "Now let us see how their nerve holds up when they see what became of their companions!", sourceObjectiveStatus = "unverified-source-field" }
quests[11870] = { id = 11870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Reach", description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!\n\nShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.\n\nMake haste, Liandra awaits you there!", sourceObjective = "Seek out Hierophant Liandra at the Abandoned Reach.", completion = "Cenius sent you? Well you're not a moment too soon!", sourceObjectiveStatus = "unverified-source-field" }
quests[11871] = { id = 11871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not On Our Watch", description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!", sourceObjective = "Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.", progress = "We will give those animals a proper burial.", completion = "A job well done, {name}. Now we strike at the pirate leader!", sourceObjectiveStatus = "unverified-source-field" }
quests[11872] = { id = 11872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nefarious Clam Master...", description = "It's despicable, really, to anoint one's self as the \"Clam Master,\" as if they hold mastery over the creatures of the sea. None may make such claims!\n\nThis \"Clam Master\" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.\n\nOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.", sourceObjective = "Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment.", progress = "Do you bring me good news?", completion = "Excellent work, {name}. We are closing in on Nesingwary!", sourceObjectiveStatus = "unverified-source-field" }
quests[11873] = { id = 11873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Fizzcrank the News", description = "Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way.\n\nI'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort.\n\nI only wonder what the old man would've done himself if he'd been flying with us. I miss those days.", sourceObjective = "Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.", completion = "<Fizzcrank listens to your report, looking somewhat relieved.>\n\nI should've gone with them. We might've been able to complete the mission without losing any pilots.\n\nTailspin is right, though, we have you to thank for what you've been able to salvage. Your efforts may just make the difference in the fight against the Nerubians.", sourceObjectiveStatus = "unverified-source-field" }
quests[11875] = { id = 11875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining the Advantage", description = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying <his/her> trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", sourceObjective = "Bring 8 Nether Residue to Emissary Mordin in Shattrath City.", progress = "Have you any residue for me?", completion = "Thank you for your help, {name}. No contribution to the war effort is too small. Our men are going to need every advantage they can get in this battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[11876] = { id = 11876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Those That Cannot Help Themselves", description = "They're majestic beasts, aren't they?\n\n<Lathorius points towards the mammoths of the northern tundra.>\n\nWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.\n\n<Lathorius' face contorts with anger.>\n\nIt's the whimpers that drive me to madness, {name}. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us.\n\nTake this hammer and smash those traps. Free the calves!", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves.", progress = "They must be freed!", completion = "<Arch Druid Lathorius wipes away his tears.>\n\nThey never stood a chance. Now orphaned, they will surely die on their own.", sourceObjectiveStatus = "unverified-source-field" }
quests[11877] = { id = 11877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunfury Attack Plans", description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.\n\nWe must not allow this to happen, {name}. Each and every blade is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, {name}.", sourceObjective = "Lord Torvos in Shattrath wants you to capture the Sunfury Attack Plans.", progress = "Have you returned with the plans?", completion = "<Lord Torvos accepts the plans and looks over them.>\n\nYou've done the offensive a great service, {name}, but we should not rest. I wouldn't put it beyond our foes to plan more mischief in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[11878] = { id = 11878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khu'nok Will Know", description = "Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.\n\nBut there is a way! Hope yet remains!\n\nNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.", sourceObjective = "Take the Orphaned Mammoth Calf to Khu'nok the Behemoth in the Borean Tundra.", progress = "<Khu'nok looks upon you with intelligence unusual for a beast.>", completion = "<You hear a voice in your head. It is Khu'nok.>\n\nYour name has been heard in the whistling winds, {name}. You have done a great thing for my kin. For this we will consider you an ally. Alas, our torment cannot end without bloodshed and violence.\n\nThe price of peace for the mammoths will be the death of Kaw...", sourceObjectiveStatus = "unverified-source-field" }
quests[11879] = { id = 11879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaw the Mammoth Destroyer", description = "You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!\n\nVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise.\n\nDestroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.", sourceObjective = "Kill Kaw the Mammoth Destroyer and recover Kaw's War Halberd. Deliver Kaw's War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.", progress = "What happened?", completion = "<Lathorius takes the halberd from you.>\n\nIs this what I think it is?\n\n<Lathorius grins.>\n\nSmashing! Outstanding! Another of Nesingwary's lackeys brought to justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[11880] = { id = 11880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Multiphase Survey", description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?", sourceObjective = "Harbinger Haronem in Shattrath City wants you to use the Multiphase Spectrographic Goggles to take 6 Multiphase Readings.", progress = "Did you get those readings? That gnome will scream at me again if I don't get his precious data.", completion = "Thanks for your help. You don't know what it's like to have to deal with \"Doctor\" Wafflefry over there. In between his \"checkups\" on my progress, he's busy hawking some gadget or another derived from his military inventions.", sourceObjectiveStatus = "unverified-source-field" }
quests[11881] = { id = 11881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Load'er Up!", description = "Have you seen the flying machines buzzing around? That's gnomish innovation at its finest.\n\nI've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.\n\nBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.", sourceObjective = "Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka'le Village without losing all her cargo.", progress = "Don't fail! I'm counting on you.", completion = "<Fezzix looks over the salvage.>\n\nJenny's a little roughed up, but she'll be fine. As for the salvage, it's a bit more... piecemeal than I had hoped, but I should be able to find a use for it. You're not off the hook yet, though. We're going to rebuild this baby.", sourceObjectiveStatus = "unverified-source-field" }
quests[11882] = { id = 11882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", sourceObjective = "Speak to a Master Fire Eater in any Alliance capital.", completion = "Well met. You've come learn some new ways to handle fire?", sourceObjectiveStatus = "unverified-source-field" }
quests[11883] = { id = 11883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Dancing?", description = "You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.", sourceObjective = "Speak to a Master Fire Dancer in any Horde capital.", sourceObjectiveStatus = "unverified-source-field" }
quests[11884] = { id = 11884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nedar, Lord of Rhinos...", description = "West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured or young - rhinos unable to defend themselves against his cowardly attacks. To add insult to injury, Nedar has raised a rhino of his own to become his mount and bodyguard.\n\nIt is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Nedar's tainted rhino must be disposed of... Kill them both and return to me.", sourceObjective = "Killinger the Den Watcher at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Nedar, Lord of Rhinos and his companion, \"Lunchbox.\"", progress = "Have you put them down?", completion = "At least for now the rhinos will know peace. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11885] = { id = 11885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.", sourceObjective = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing.", progress = "Have you completed your task, {name}?", completion = "Excellent!  Take this.  I've prepared this bundle with items symbolizing the foes you've defeated.  They will allow you to summon Terokk.\n\nBeware, {name}.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11886] = { id = 11886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Activity", description = "While celebration has its place, {class}, some of us must look to graver matters.\n\nWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", sourceObjective = "Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.", progress = "What have you uncovered?", completion = "This is worrisome, friend. It hints at a much larger plot beyond simple agitation of the local fire and water elements, and something here bears investigation...", sourceObjectiveStatus = "unverified-source-field" }
quests[11887] = { id = 11887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Supplies", description = "Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.\n\nBringing a few of these kits to Fezzix might just be worth a nice bonus.", sourceObjective = "Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka'le Village.", progress = "What is it you have there?", completion = "Gnomish tools? For me? These should make rebuilding that flying machine even easier than I expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[11888] = { id = 11888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Taunka'le Village", description = "{race}, the chieftain is making me wait... time that Taunka'le does not have!\n\nThere has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people.\n\nTaunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains.\n\nSpeak with Sage Earth and Sky when you arrive.", sourceObjective = "Speak with Sage Earth and Sky at Taunka'le Village.", completion = "It does not surprise me that the orc chieftain does not have time to hear of our troubles. The ambassador's efforts will likely be like so much mist blowing in the wind.\n\nBut you are here now. We shall see if he chose well in sending you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11889] = { id = 11889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death From Above", description = "We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.\n\nI've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.", sourceObjective = "Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep.", progress = "You're back.  Good news, hopefully?", completion = "We'll beat them if they come by land and we'll beat them if they come by air.  If these motherless undead come by sea we're going to give them the beating of their lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[11890] = { id = 11890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Are They Up To?", description = "The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.\n\nI want you to go out to their pumping station and observe what has befallen them. Return to me after.", sourceObjective = "Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka'le Village.", completion = "Troubling news indeed.\n\nMy people are leaving this place soon. We are going to break through the Scourge lines to get to our capital, Icemist, in the Dragonblight.\n\nBut, before we do that, we must deal with what the gnomes in their insanity have wrought.", sourceObjectiveStatus = "unverified-source-field" }
quests[11891] = { id = 11891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Innocent Disguise", description = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?\n\nMuch could be learned from listening to these proceedings, {race}. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", sourceObjective = "Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon.", progress = "Have you learned their secrets?", completion = "They seek to summon a frost lord into our world? No! They cannot tip the balance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11892] = { id = 11892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assassination of Harold Lane", description = "You have done much for the animals of the Borean Tundra, {name}. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget.\n\nHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here.\n\n<Lathorius hands you an intricately carved oak horn.>\n\nFind Lane and kill him. Use this horn should you require our aid.", sourceObjective = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Harold Lane.", progress = "Is the Borean Butcher slain?", completion = "Alas, Nesingwary is gone. Perhaps he was never here to begin with...\n\n<Lathorius sighs.>\n\nThe demon is a slippery one, but his days are numbered. We will find him and when we do...", sourceObjectiveStatus = "unverified-source-field" }
quests[11893] = { id = 11893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Elements", description = "I kept trying to tell that silly goblin his machines are unreliable.\n\nBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.\n\nTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.", sourceObjective = "Dorain Frosthoof at Taunka'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.", progress = "Have you charged the totem?", completion = "<Dorain nods.>\n\nGood. This should be sufficient to show Fezzix exactly what I've been trying to tell him.", sourceObjectiveStatus = "unverified-source-field" }
quests[11894] = { id = 11894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patching Up", description = "Remember all that gnomish duct tape you brought me?\n\nWell, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly.\n\nDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.", sourceObjective = "Fezzix Geartwist at Taunka'le Village wants you to bring him 5 Steam Cured Hides.", progress = "Did you get that cured caribou hide for me?", completion = "Fantastic! A few more tweaks and I'll be an airborne goblin!", sourceObjectiveStatus = "unverified-source-field" }
quests[11895] = { id = 11895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master the Storm", description = "From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.\n\nBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.\n\nIf others are there, it is enough that you all work together to defeat it. Return to me after, {class}.", sourceObjective = "Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka'le Village.", progress = "Have you mastered the storm yet?", completion = "I feel the power of the storm coursing through you!\n\nYou are ready, {name}. Let us begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11896] = { id = 11896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weakness to Lightning", description = "You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.\n\nTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.\n\nOnce the robots are weakened by the power of the storm, dismantle them utterly!", sourceObjective = "While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station.\n\nAfterward, return to Sage Earth and Sky at Taunka'le Village.", completion = "With their robotic minions dealt with, it is time for us to move on to bigger prey. Unfortunately, even now I feel the power of the storm waning from within you.\n\nNevertheless, it served its purpose, and I think that you're more than capable of taking the next step without it.", sourceObjectiveStatus = "unverified-source-field" }
quests[11897] = { id = 11897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plug the Sinkholes", description = "The Scourge are showing no sign of letting up, {name}.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.\n\nIf there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion.\n\nTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.", sourceObjective = "Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.", progress = "Did you succeed, {name}?  We need to slow down the Scourge or Valiance Keep will be overrun.", completion = "Excellent work, {name}.  Without you, Valiance Keep might've not held against the attackers.  Thanks to your help we'll live to fight another day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11898] = { id = 11898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Through", description = "On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.\n\nBe cautious, {name}. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.\n\nYou must find your way through the necropolis to the prince's seat. If you fail to defeat him, {name}, I fear my people will never know the safety Icemist offers.", sourceObjective = "Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka'le Village.", progress = "Have you defeated Prince Valanar?", completion = "With the prince defeated, the Scourge presence in Borean Tundra is broken. I have no illusions that they will stay away for long, which is why I must focus on preparing Durm to lead the villagers on their way to Icemist.\n\n<The chieftain shakes his head slowly.>\n\nFor all the disagreements I've had with Durm, I trust his judgment and his abilities. I cannot bring myself to abandon Taunka'le, so I will defend it until I am slain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11899] = { id = 11899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls of the Decursed", description = "The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.\n\nThey are an unnatural danger and must be dealt with.\n\nTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.", sourceObjective = "Use The Greatmother's Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka'le Village once you have done so.", completion = "Now we must free the souls that you have captured.", sourceObjectiveStatus = "unverified-source-field" }
quests[11900] = { id = 11900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Meters", description = "I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially!\n\nI need the Nexus monitored regularly as I work to develop a solution.\n\nI've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.", sourceObjective = "Archmage Berinand at the Transitus Shield has asked you to collect the readings from his instruments in Coldarra.", progress = "Have you read all of my instruments, {class}?", completion = "This is worse than I expected.\n\nMalygos is channeling too much power to this place. If he's not stopped, Azeroth will be the next Outlands!\n\nFortunately, I believe that I've engineered a temporary solution....", sourceObjectiveStatus = "unverified-source-field" }
quests[11901] = { id = 11901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Military? What Military?", description = "There's Scourge everywhere, {class}.  We've organized the farmers and miners into a militia, but this just won't cut it.\n\nThe one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days!\n\nIf you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.", sourceObjective = "Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there.", completion = "Your stomach feels uneasy as you approach the grain.  The smell is nearly unbearable.", sourceObjectiveStatus = "unverified-source-field" }
quests[11902] = { id = 11902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pernicious Evidence", description = "The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine.\n\nYou'd best bring word back to Gerald Green.", sourceObjective = "Return to Gerald Green in Farshire.", completion = "Those poor lads... they never had a chance!\n\nThis sure sounds like an inside job.  Probably a Cult of the Damned infiltrator.  Curse those madmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11903] = { id = 11903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Time for Action", description = "Well, {name}.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.\n\nWe have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!", sourceObjective = "Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.", completion = "You've communicated with the Scourge in the only language they understand: violence and death.  Unfortunately they just keep coming!", sourceObjectiveStatus = "unverified-source-field" }
quests[11904] = { id = 11904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruits of Our Labor", description = "The Scourge just keeps coming... but we can't give up!  Listen, {name}.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.\n\nThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.\n\nThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.", sourceObjective = "Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart. Return to Gerald Green in Farshire when you've completed this task.", progress = "The ore, {name}, is it safe?", completion = "I thank you, {name}.  This ore will be of vital importance to the Alliance in the times to come.  I'd like to think we've made a difference today.", sourceObjectiveStatus = "unverified-source-field" }
quests[11905] = { id = 11905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postponing the Inevitable", description = "Azeroth's ley lines are being redirected to the Nexus.\n\nThe influx of arcane energies is tearing a rift between dimensions.\n\nI cannot stop it, but I've discovered a way to slow it down.\n\nTake this and activate it near the forming rift.", sourceObjective = "Image of Warmage Kaitlyn in the Nexus wants you to use the Interdimensional Refabricator near the rift.", progress = "Have you been to the rift in the Nexus?", completion = "Excellent work, {name}. The tremors have already begun to subside.\n\nWith any luck, your efforts have granted us sufficient time to find a way to thwart Malygos' efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11906] = { id = 11906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up the Pools", description = "<A single tear rolls down the face of Iron Eyes.>\n\nI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, {race}.\n\nThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.\n\nReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.", sourceObjective = "Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka'le Village.", progress = "If we do not take care of the land, she will not suffer us to live for long.", completion = "It is the taunka way to leave the land pristine before we move on.\n\nWe will be traveling to our capital, Icemist, very soon. You have helped by allowing us to depart that much more quickly.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11907] = { id = 11907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sub-Chieftains", description = "It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.\n\nWe must put an end to them!\n\nOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.\n\nThe stations are centered on the spinning lights in the pools surrounding the pumping station.\n\nHurry, {name}!", sourceObjective = "Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka'le Village.", completion = "Thank you, {name}.\n\nWith these odd creatures destroyed, dealing with the rest of the pools should now be a simple matter.\n\nWe owe you a debt of gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11908] = { id = 11908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reference Material", description = "I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however.\n\nI think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge.\n\nI'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?", sourceObjective = "Jeremiah Hawning wants you to retrieve the book \"Fields, Factories and Workshops\" from the burning building next to the mine in Farshire.", progress = "Did you get my book back?", completion = "Excellent!  The information I need should be in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11909] = { id = 11909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defeat the Gearmaster", description = "Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!\n\nThe winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west.\n\nMost likely, he'll be found in the command hut on top of the structure. Go inside and research his works.\n\n{name}, you must confront Mechazod if we are to survive!", sourceObjective = "Research the Gearmaster's Manual and return Mechazod's Head to Greatmother Taiga at Taunka'le Village.", progress = "Is it over then? Has the threat of Gearmaster Mechazod been eliminated?", completion = "<The greatmother breathes a heavy sigh of relief.>\n\nIt is done then... you have saved us! If you hadn't stopped him here, then who knows how far this mistake of the gnomes would have spread?\n\nWith the threats from the blue dragons and the Nexus War, not to mention the Lich King, the last thing we need is a mad creation of the Titans running loose!\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11910] = { id = 11910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Ancients", description = "It's become clear that the instability in the region has had an effect on its indigenous creatures.\n\nI've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here.\n\nFor my studies, I'll need samples from both. Do hurry....", sourceObjective = "Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra.", progress = "Have you collected the samples I requested?", completion = "Yes, yes. These shall do nicely.\n\nThank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11911] = { id = 11911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quickening", description = "I've learned more in my short time here than in decades of studies.\n\nThe ancients here are being exposed to incredible levels of arcane energy. It's literally transforming them into something...\n\nI'm confident that there's a final stage in their metamorphosis. Find me some evidence of their final state.", sourceObjective = "Image of Warmage Kaitlyn in the Nexus wants you to collect 5 Arcane Splinters from Crystalline Protectors.", progress = "The Crystalline Ancients... Do they exist?", completion = "Fascinating!\n\nAnd they're aggressive too, you say. That would suggest that some intelligence is behind this manipulation. It may not be natural at all....\n\nPlease, {name}, accept this as a token of our gratitude for your efforts. Dalaran will hear of your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[11912] = { id = 11912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuts for Berries", description = "Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken.\n\nOur supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me.\n\nMaybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts.\n\nTo the point, our food supply is nearly spent. Please, gather what you can and bring it to me.", sourceObjective = "Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra.", progress = "Have you been able to find any food?", completion = "Well, it's not much, but it should keep us alive for another day.\n\nI believe you'll find this to be a fair price for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[11913] = { id = 11913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take No Chances", description = "I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside.\n\nWe don't have time to sort the good grain from the bad.  We must act quickly and burn it all.\n\nTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.", sourceObjective = "Wendy Darren wants you to use Wendy's Torch to burn 8 sacks of Farshire Grain.", completion = "I thank you, {name}.  I would hate to see survivors of the attack on Farshire stumble upon plagued grain.", sourceObjectiveStatus = "unverified-source-field" }
quests[11914] = { id = 11914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep the Secret Safe", description = "Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us.\n\nOne of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise.\n\nI could use your help, {name}.\n\nVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.", sourceObjective = "Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.", progress = "Do you have the mana essences I asked for?", completion = "Your service to Dalaran will not go unnoticed, {race}.\n\nI hope you find this payment sufficient.", sourceObjectiveStatus = "unverified-source-field" }
quests[11915] = { id = 11915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", sourceObjective = "Speak to a Master Flame Eater in any Horde capital.", completion = "Greetings. You've come learn some new ways to handle fire?", sourceObjectiveStatus = "unverified-source-field" }
quests[11916] = { id = 11916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Champion", description = "You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, {name}, that the Horde is now firmly entrenched in Northrend.\n\nBut our work has only just begun. We must march to Icecrown and we must tear down its walls!\n\nYour next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.", sourceObjective = "Seek out Chieftain Wintergale at Taunka'le Village.", completion = "I fear that you may be too late, champion. Many of my brothers and sisters have already abandoned Taunka'le, seeking shelter in the Dragonblight, far to the east.\n\nThere is much work left to be done here and few willing to lend us their strength...", sourceObjectiveStatus = "unverified-source-field" }
quests[11917] = { id = 11917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11918] = { id = 11918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Training", description = "This is war, mortal, and we are the tip of the spear.\n\nYour little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more.\n\nWe are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy.\n\nGo now. Busy yourself while I decide what to do with you.", sourceObjective = "Raelorasz at the Transitus Shield wants you to slay 10 Coldarra Spellweavers.", completion = "Alright, {class}, now that you've become familiar with the enemy it's time for you to get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[11919] = { id = 11919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake Hunt", description = "The blues have begun to cover their drakes in mysterious runes. I must discover their significance.\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.\n\nTheir hatchlings feed around the northwest edge of the valley.", sourceObjective = "Raelorasz wants you to use Raelorasz's Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", progress = "Have you managed to capture one of the Nexus Drakes?", completion = "The fate of these young drakes need not burden your conscience, {race}. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes. We shall take no more lives than we must.", sourceObjectiveStatus = "unverified-source-field" }
quests[11920] = { id = 11920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", sourceObjective = "Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep.", completion = "Cultists?  Below deck?  I ought to have my whole crew flogged!\n\nListen... why don't we have Admiral Cantlebree take care of this... situation?", sourceObjectiveStatus = "unverified-source-field" }
quests[11921] = { id = 11921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", sourceObjective = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", sourceObjectiveStatus = "unverified-source-field" }
quests[11922] = { id = 11922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", sourceObjective = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", sourceObjectiveStatus = "unverified-source-field" }
quests[11923] = { id = 11923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", sourceObjective = "Catch 4 torches in a row, then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11924] = { id = 11924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", sourceObjective = "Catch 10 torches in a row, then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", sourceObjectiveStatus = "unverified-source-field" }
quests[11925] = { id = 11925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", sourceObjective = "Catch 10 torches in a row, then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, {name}?  You looked great out there.  A real juggling master!", sourceObjectiveStatus = "unverified-source-field" }
quests[11926] = { id = 11926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", sourceObjective = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!", sourceObjectiveStatus = "unverified-source-field" }
quests[11927] = { id = 11927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Word on the Street", description = "Hey, {name}.  There's a girl in the inn that's asking about you.  Her name's Leryssa.\n\nI don't think she knows you, but she said she needed your help.  She sounded really desperate.", sourceObjective = "Find Leryssa at the inn in Valiance Keep", completion = "Thank you for coming to see me.  I didn't know who else to contact.", sourceObjectiveStatus = "unverified-source-field" }
quests[11928] = { id = 11928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farshire", description = "My lads should be able to take it from here, {name}.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.\n\nWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.\n\nGerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.", sourceObjective = "Travel to Farshire in Borean Tundra and speak to Gerald Green.", completion = "You're here to help?  You're just in time then!", sourceObjectiveStatus = "unverified-source-field" }
quests[11929] = { id = 11929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Taunka'le Village", description = "We are lost, {name}. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.\n\nI have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.\n\n<Wintergale points east.>\n\nYou must help get my people to safety, {name}. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!", sourceObjective = "Speak to Mother Tauranook outside the gates of Taunka'le Village.", completion = "<Mother Tauranook wipes her tears away.>\n\nThere was once a time when I could walk across this tundra and the snow would fill my view for as far as I could see.\n\nBut the snow has left us - signaling that our time here has come to an end. We leave behind Taunka'le Village and the Borean Tundra with many happy memories...\n\n<Mother Tauranook whimpers.>\n\nPerhaps the future will welcome our return - along with the snow.", sourceObjectiveStatus = "unverified-source-field" }
quests[11930] = { id = 11930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Across Transborea", description = "The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety!\n\nWartook Iceborn waits for you across the bridge leading into the Dragonblight.", sourceObjective = "Escort the Taunka'le Evacuees across Transborea to Wartook Iceborn on the border of the Dragonblight.", completion = "<Wartook looks upon you grimly.>\n\nIcemist is no more...", sourceObjectiveStatus = "unverified-source-field" }
quests[11931] = { id = 11931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Code", description = "I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me.\n\nWithout a codex, it will take more time than we can afford for me to interpret them.\n\nNot far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation.\n\nHurry, mortal. Malygos gains strength with every passing moment.", sourceObjective = "Raelorasz at the Transitus Shield wants you to get the Azure Codex from Inquisitor Caleras and collect 3 Shimmering Runes from his Coldarra Spellbinders.", progress = "Hurry, mortal.\n\nMalygos gains strength with every passing moment.", completion = "You have done well, {race}.\n\nLet us hope for a clue that we can use against Malygos.", sourceObjectiveStatus = "unverified-source-field" }
quests[11932] = { id = 11932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cowards and Fools", description = "Listen, {name}.  No offense, but the operation they put Thassarian in charge of was pure suicide.\n\nA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun.\n\nIf you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.", sourceObjective = "Speak to Ataika in Kaskala, northeast of Valiance Keep.", completion = "I remember the man you speak of.  He bore the marks of Karkut.\n\nMay Karkut protect our fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11933] = { id = 11933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Exodar's Flame", description = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", sourceObjective = "Return the Flame of the Exodar to the Festival Talespinner.", progress = "You're practically glowing, {race}. What do you have there?", completion = "This fire seems new... Yet, you say it came from the Exodar? Fascinating! To make your way into that ship...  Of course, I'll pay you for this. If you find anything else like this, be sure to speak with me again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11935] = { id = 11935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Silvermoon's Flame", description = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", sourceObjective = "Return the Flame of Silvermoon to the Festival Loremaster.", progress = "You're practically glowing, {race}. What do you have there?", completion = "What a glorious fire! You received this from Silvermoon, you say? Unbelievable! With the flames of all four cities, who knows what we could accomplish?", sourceObjectiveStatus = "unverified-source-field" }
quests[11936] = { id = 11936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatching a Plan", description = "Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you.\n\nThe blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn.\n\nI don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.", sourceObjective = "Raelorasz at the Transitus Shield wants you to kill Coldarra Wyrmkin and use their frozen axes to break 5 blue dragon eggs.", progress = "Have you destroyed the blues' eggs, {class}?", completion = "It pains me to order the destruction of dragon eggs, enemy or no.\n\nMay the ends of this war justify the means....", sourceObjectiveStatus = "unverified-source-field" }
quests[11938] = { id = 11938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buying Some Time", description = "Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however.\n\nI won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out.\n\nI want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.", sourceObjective = "Thassarian at the Wailing Ziggurat in Borean Tundra wants you to inflict 20 casualties against the Scourge inside the Temple City of En'kilah. Use Lurid's Bones if you need assistance.", progress = "Is it done?", completion = "That should buy us some time.  Isidorus has been cooperative, but I really needed that alone time with the lich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11940] = { id = 11940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake Hunt", description = "I need more drake hatchlings to continue researching the runes covering their bodies.\n\nThey can be found around the northwest edge of the valley....\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.", sourceObjective = "Raelorasz wants you to use the Blood-tipped Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", progress = "Have you recovered a drake hatchling for my studies?", completion = "The fate of these young drakes need not burden your conscience, {race}. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes.\n\nRest assured, we shall take no more lives than we must.", sourceObjectiveStatus = "unverified-source-field" }
quests[11941] = { id = 11941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puzzling...", description = "Something about this scrap of metal prevents you from casting it aside.\n\nPerhaps Raelorasz might be able to shed some light on its purpose.", sourceObjective = "Bring the Scintillating Fragment to Raelorasz at the Transitus Shield.", progress = "What have you found, {class}?", completion = "It was wise of you to bring this to me, {name}.\n\n\n\nIf you truly desire to contribute to our efforts, no matter the risk, I shall share with you its meaning.", sourceObjectiveStatus = "unverified-source-field" }
quests[11942] = { id = 11942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", description = "The lich has spoken, {name}.  The high priests of En'kilah hold the secret to entering Naxxanar.\n\nGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.\n\nReturn once you've obtained the three scrolls.", sourceObjective = "Thassarian at the Wailing Ziggurat wants you to go to the Temple City of En'kilah and retrieve High Priest Talet-Kha's Scroll from the Spire of Pain, High Priest Naferset's Scroll from the Spire of Decay and High Priest Andorath's Scroll at the Spire of Blood.", progress = "Taking your time, are you?  I don't know how much longer I can keep this lich restrained.", completion = "Excellent work, {name}.  Now for one last bit of information.", sourceObjectiveStatus = "unverified-source-field" }
quests[11943] = { id = 11943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cell", description = "You've discovered a fragment of a special prison, {name}.\n\nMalygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger.\n\nIn hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments.\n\nThey are likely to be in the possession of Malygos' most trusted underlings.", sourceObjective = "Raelorasz at the Transitus Shield wants you to obtain the Prison Casing from General Cerulean and the Energy Core from Warbringer Goredrak.", progress = "Have you discovered any other pieces to the prison?", completion = "<The pieces you've collected begin to glow brightly in Raelorasz' hands.>\n\nIt is done.\n\nI sense a strong presence within this prison. Let us hope it proves to be an ally.", sourceObjectiveStatus = "unverified-source-field" }
quests[11944] = { id = 11944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrounded!", description = "Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men.\n\nWe'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route.\n\nIf you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.", sourceObjective = "Corporal Venn at Death's Stand wants you to slay 7 Ziggurat Defenders.", progress = "Did you make any progress?  We're in a bind here.", completion = "That should buy us some time, {name}.  We'll hope against hope for reinforcements from Valiance Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[11945] = { id = 11945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for the Worst", description = "Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr.\n\nThe sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes.\n\nThere is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them.\n\nThey will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.", sourceObjective = "Utaik wants you to gather 8 Kaskala Supplies in Kaskala.", progress = "Have you succeeded, {name}?  Our relatives in Unu'pe are depending on your efforts.", completion = "I thank you, {name}.  These supplies will feed our cousins and children.  Even if Kaskala falls, our tribes must carry on.", sourceObjectiveStatus = "unverified-source-field" }
quests[11946] = { id = 11946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keristrasza", description = "I am... free?\n\nI was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal.\n\nWhen I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness.\n\nPerhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done.\n\nI need your help, {name}.", sourceObjective = "Keristrasza wants you to speak to her when you are ready to prepare for a confrontation with Malygos.\n\nIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.", completion = "We cannot wait for me to regain my strength.\n\nI must rely on you to make our preparations....", sourceObjectiveStatus = "unverified-source-field" }
quests[11947] = { id = 11947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11948] = { id = 11948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11949] = { id = 11949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Without a Fight!", description = "Kaskala is a sacred place for us, {race}.  Our ancestors were guided here by the spirit of Tayutka herself.\n\nNow these foul creatures attack us from the mists without any provocation.\n\nWe will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.", sourceObjective = "Ataika wants you to slay 12 Kvaldir Raiders in Kaskala.", progress = "We are fighting tooth and nail, {name}.  We'll not give these Kvaldir an inch without making them pay for it dearly.", completion = "I thank you, {name}.  I will be deeply in your debt if we ever make it out of here alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11950] = { id = 11950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muahit's Wisdom", description = "Listen, {name}.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.\n\nMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.\n\nYou are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.", sourceObjective = "Find Elder Muahit in Kaskala.", completion = "Ataika sent you, didn't he?  I am not to be swayed.\n\nAll is not lost.  The spirits are still with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11951] = { id = 11951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bait and Switch", description = "During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him.\n\nThere is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger.\n\nI suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....", sourceObjective = "Keristrasza has asked you to collect 10 Crystalized Mana Shards from around Coldarra.\n\nIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.", progress = "Have you gathered the mana shards I require?", completion = "Thank you, {name}.\n\nI am drained from the effects of my confinement and my strength is returning ever so slowly.\n\nI shall use the power from these crystals wisely. They are a byproduct of Malygos' malevolent schemes. With luck, they will play a part in his undoing.", sourceObjectiveStatus = "unverified-source-field" }
quests[11952] = { id = 11952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11953] = { id = 11953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11954] = { id = 11954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", sourceObjective = "Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city.", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11955] = { id = 11955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune, the Frost Lord", description = "I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", sourceObjective = "Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister.", completion = "Thank the spirits you're here! We must summon Ahune quickly before it's too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[11956] = { id = 11956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Phylactery", description = "No time for small talk, {name}.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers.\n\nThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.\n\nThe lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him.\n\nReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.", sourceObjective = "Go to Death's Stand and ride Dusk to the location of Tanathal's Phylactery. Obtain it and bring it back to Thassarian inside the Wailing Ziggurat.", progress = "You're back, {name}.  Did you get the phylactery?", completion = "Just in time, {name}.  Pinning down a lich is not as easy as it looks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11957] = { id = 11957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saragosa's End", description = "Using the mana crystals you provided, I have created this Power Focus.\n\nSaragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse....\n\nPrepare yourself, {name}, and speak to me again when you are ready to face Saragosa.", sourceObjective = "Keristrasza wants you to use the Power Focus to lure Saragosa, and then defeat her.", progress = "Saragosa must not be allowed to live!", completion = "This world is a better place now that Saragosa is no more, but our work is not yet finished.\n\nThe time has come to strike at Malygos himself!", sourceObjectiveStatus = "unverified-source-field" }
quests[11958] = { id = 11958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Nothing Go To Waste", description = "The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north.\n\nCombined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here.\n\nAs a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.", sourceObjective = "Retrieve 6 Stolen Moa'ki Goods from the wolvar. Return them to Elder Ko'nani at Moa'ki Harbor.", progress = "The natural balance has been tipped over and over of late.\n\nI hope that you will be able to help us survive the upheaval of our way of life.", completion = "I will not say that I am pleased to ask you to do such things on our behalf. It is all we can do to prepare quickly for our departure, though we know not yet where we go.\n\nMy sorcerers tell me that you are here to save the land from He Who Walks in Shadow.\n\nI trust that you will save the peoples of the land as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[11959] = { id = 11959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay Loguhn", description = "Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die!\n\nHe's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays.\n\nYou will find the \"Render of Flesh\" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.", sourceObjective = "Smear the Blood of Loguhn upon yourself and then return to Elder Ko'nani at Moa'ki Harbor.", progress = "Is that Loguhn's blood or your own, {race}?", completion = "Loguhn's honorable sacrifice at your hands is exactly what my people need. Now we will make the most of the wolvar in-fighting for his place.\n\nIt will have to be enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[11960] = { id = 11960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", sourceObjective = "Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor.", progress = "How many pups could you have possibly saved in so short a time?", completion = "Well, I guess you saved plenty of them. Thank you, {race}.\n\nNow the wolvar will have a chance of surviving along with us. If we survive at all, that is.\n\nDo you think that you could return tomorrow so that we can save more of the pups?", sourceObjectiveStatus = "unverified-source-field" }
quests[11961] = { id = 11961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Watch Over Us", description = "Powerful spirits watch over my tribe -- Kaskala will not be lost.\n\nIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.\n\nIssliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, {name}.  Don't let my nephew's death be in vain.", sourceObjective = "Elder Muahit at Njord's Breath Bay wants you to find Iruk's corpse in the water and retrieve Issliruk's totem.", progress = "The totem, {race}.  Do you have it?", completion = "Can you feel Issliruk's presence, {name}?  He does not want his children to perish at the hand of the mist-walkers.", sourceObjectiveStatus = "unverified-source-field" }
quests[11962] = { id = 11962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Delivery", description = "That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep.\n\nIf Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up.\n\nTake this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.", sourceObjective = "Deliver the Crate of Farshire Ore to Hilda Stoneforge in Valiance Keep.", progress = "What do you have there?", completion = "Ore from Farshire?  We weren't scheduled for a shipment just yet.  Is something wrong?", sourceObjectiveStatus = "unverified-source-field" }
quests[11963] = { id = 11963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons for Farshire", description = "Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines.\n\nWe cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons.\n\nThese were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.", sourceObjective = "Return to Gerald Green in Farshire.", completion = "Hilda's sending us weapons?  That's excellent news, {name}.  I was about ready to tell the lads to pack things up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11964] = { id = 11964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Summer Scorchlings", description = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.", sourceObjective = "The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11965] = { id = 11965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms!", description = "Farshire has a fighting chance now, {name}.  That's all we could've asked for and you've made it possible.\n\nAll we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.\n\nIt's time to show the Scourge what we're made of.", sourceObjective = "Go to the town hall building in Farshire and ring the bell inside of it.", progress = "Have you rallied the survivors, {name}?", completion = "Thanks once again for aiding us, {name}.  The people of Farshire will always remember you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11966] = { id = 11966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense for the Festival Scorchlings", description = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.", sourceObjective = "The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement.", progress = "A fiery salutations to you, honored {class}.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, {name}.  Take it, and leave me be... I must attend to this precious fuel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11967] = { id = 11967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustering the Reds", description = "Malygos is certainly aware that something is amiss.\n\nI know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa.\n\nTake me to Raelorasz at once, {name}. He must rouse every dragon he commands to face Malygos.", sourceObjective = "Keristrasza has asked you to bring her to Raelorasz at the Transitus Shield.", progress = "You have news for me, {name}?", completion = "Word of Keristrasza's rescue has reached my ears. You are to be commended.\n\nI am eager to speak with her again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11968] = { id = 11968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tides Turn", description = "The spirits have heard our cry for help, {name}.  It's a sign that Kaskala might yet be saved.\n\nTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.", sourceObjective = "Elder Muahit wants you to kill Heigarr the Horrible in Njord's Breath Bay.", progress = "Have you done what I asked of you, {name}?", completion = "You've done us a great favor, {race}.  The fight is not yet won, but my people now have a chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11969] = { id = 11969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Springing the Trap", description = "We owe this opportunity in great part to your efforts, {name}.\n\nIt is only fitting that you initiate the attack on Malygos.\n\nTake this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.", sourceObjective = "Raelorasz wants you to use Raelorasz' Spark at the signal fire in Coldarra.", progress = "Did you meet with Keristrasza?", completion = "We have dealt a blow to Malygos, but it has come at a high price.", sourceObjectiveStatus = "unverified-source-field" }
quests[11970] = { id = 11970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Summer Lore", description = "The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.\n\nThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn.", sourceObjective = "Speak to the Festival Loremaster in any Alliance capital.", completion = "I'll be happy to tell you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11971] = { id = 11971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spinner of Summer Tales", description = "The festival is a time for fun and laughter, there's no mistake. It's important, however, that you understand the origins of this holiday. Education should be sought out and savored.\n\nThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", sourceObjective = "Speak to the Festival Talespinner in any Horde capital.", completion = "I'll be happy to tell you what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11972] = { id = 11972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Ahune", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", sourceObjective = "Bring the Ice Shards to Luma Skymother.", progress = "Greetings, {name}.  You look worried, but you shoud rejoice.  The Frost Lord is defeated!", completion = "Yes, these shards hold the final essence of the Frost Lord in this land.  We will dispose of them and banish Ahune to the nether regions of cold.\n\nThank you, {name}.  Your name will echo in the chants of the Earthen Ring for days without end.  Please honor us by accepting this vestige, a symbol of your kinship with warmth and light.", sourceObjectiveStatus = "unverified-source-field" }
quests[11973] = { id = 11973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoner of War", description = "Malygos has taken Keristrasza to serve as his consort!\n\nWe cannot allow this to come to pass.\n\nYou must do whatever it takes to spare her such a fate, {race}.", sourceObjective = "Warmage Kaitlyn wants you to free Keristrasza.", progress = "Have you located Keristrasza? Were you able to free her from her bonds?", completion = "So, it is done then....\n\nOur kind shall never forget the sacrifice Keristrasza has made for this cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11975] = { id = 11975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now, When I Grow Up...", description = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Elite Tauren Chieftain!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there.  Please!", sourceObjective = "Take your orphan, Salandria, to see the Elite Tauren Chieftain in Silvermoon City's Walk of Elders. Make sure to call for her if she is not present when you arrive.", progress = "Elite Tauren Chieftain are the coolest!", completion = "Did you see that?  They were cheering for me!!\n\nNow I know how they feel when they are up on stage singing!  I felt the power and the energy!\n\nJust like they say in their song!\n\nMy mind is made up, I am going to be a rock star when I grow up!", sourceObjectiveStatus = "unverified-source-field" }
quests[11976] = { id = 11976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Shards", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", sourceObjective = "Bring the Ice Shards to Luma Skymother.", sourceObjectiveStatus = "unverified-source-field" }
quests[11977] = { id = 11977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tauren Among Taunka", description = "<Wartook points northeast.>\n\nShe is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being.\n\nIf you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.", sourceObjective = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction by the Scourge.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11978] = { id = 11978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fold", description = "Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night.\n\nVenture out into the woods to the east of Westwind Refugee Camp and recover those armaments, {race}.", sourceObjective = "Emissary Brighthoof at the Westwind Refugee Camp in the Dragonblight wants you to recover 10 Horde Armaments.", progress = "Without armor and weapons our newest members will be defenseless in their trek to Agmar's Hammer.", completion = "This is exactly what we need, {name}! Brandishing Horde arms will lift their spirits and give them the protection they need against the Scourge.\n\nAre you prepared for the ceremony of initiation?\n\n\n\nYou will be the one to admit our new allies into the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11979] = { id = 11979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taunka and the Tauren", description = "The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight.\n\nLord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.", sourceObjective = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11980] = { id = 11980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Horde", description = "I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive...\n\nIf not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!", sourceObjective = "Blood Guard Roh'kill at the Westwind Refugee Camp in the Dragonblight wants you to slay 15 Anub'ar Ambushers.", progress = "Show no mercy, {race}. Slay the Anub'ar!", completion = "<Roh'kill salutes you.>\n\nYou have preserved our honor, {name}. Tor'zin and I both thank you for this selfless act!", sourceObjectiveStatus = "unverified-source-field" }
quests[11981] = { id = 11981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Kurun!", description = "The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death.\n\nA low, hoarse voice escapes from the dying warrior's mouth.\n\n\"Find... Kurun... you must find... Kurun.\"\n\nIt looks at you helplessly as you ask for any clues as to who or what Kurun might be.\n\n\"Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... \"", sourceObjective = "Speak with Kurun on the hill overlooking Thor Modan.", completion = "<You tell Kurun about the message given to you by the fallen Earthen.>\n\nThey fight bravely, but he is right. We will not overcome the iron dwarves of Thor Modan without help. My giants and the Earthen have long struggled against iron's evil, but our forces are not numerous enough to win the battle for Thor Modan. Will you aid us?", sourceObjectiveStatus = "unverified-source-field" }
quests[11982] = { id = 11982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Down Destruction", description = "Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest.\n\nEven now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.", sourceObjective = "Kurun on the hill overlooking Thor Modan wants you to disrupt the iron dwarves' work by throwing boulders into the exposed area of Thor Modan.", progress = "What have you to report?", completion = "As quickly as we're able to fill the trench, the iron dwarves keep clearing it. Our assault from above will not take the city alone. You must aid the earthen fighting in the plaza below.", sourceObjectiveStatus = "unverified-source-field" }
quests[11983] = { id = 11983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of the Horde", description = "They are ready, {name}. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.\n\n<Brighthoof hands you a scroll bearing the insignia of the Horde.>\n\nWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.\n\nTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.", sourceObjective = "Speak to the taunka at Westwind Refugee Camp and make 5 of them pledge their allegiance to the Horde.\n\nReturn the Blood Oath of the Horde to Emissary Brighthoof once you have completed this task.", progress = "They will strengthen the Horde, commander.", completion = "Thank you for doing this, Commander {name}. They had nothing left. You have given them purpose and with purpose comes hope... Hope for a new tomorrow... for a new life.", sourceObjectiveStatus = "unverified-source-field" }
quests[11984] = { id = 11984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Cages", description = "'Ol Budd's seen better days.\n\nEver since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder.\n\nFortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit.\n\nSee for yourself. Talk to Budd, take him southwest to Drak'Zin Ruins and use this cage as soon as he tags a troll.", sourceObjective = "Samir at Granite Springs wants you to use the Bounty Hunter's Cage on a drakkari troll that's been stunned by Budd.", progress = "Have you managed to cage an ice troll?", completion = "Great work, {class}. Looks like we'll be keepin' Budd around a little longer.\n\nWe'll have your cage picked up right away. Here's your share of the bounty.\n\nOh, and welcome to the camp. Stick around and I'm sure we'll find a use for ya....", sourceObjectiveStatus = "unverified-source-field" }
quests[11985] = { id = 11985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach", description = "If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city.\n\nThe tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?", sourceObjective = "Kurun on the hill overlooking Thor Modan wants you to kill Iron Thane Argrum.", progress = "Were you able to kill the commander?", completion = "Well done, {name}. The loss of the iron dwarf commander should be enough to break the remaining defenders. The Earthen should be able to deal with the survivors.", sourceObjectiveStatus = "unverified-source-field" }
quests[11986] = { id = 11986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps.\n\nThe author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard.\n\nThe back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.", sourceObjective = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Torthen Deepdig at the Westfall Brigade Encampment.", progress = "What's that you have there?", completion = "You found Brann's journal? Incredible! The league hasn't gotten a report from him in some time, and we began to fear he may have been captured or killed. What did he discover inside Thor Modan?", sourceObjectiveStatus = "unverified-source-field" }
quests[11987] = { id = 11987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLDFortune Card: Silver", sourceObjective = "You will be able to choose one of these rewards:", sourceObjectiveStatus = "unverified-source-field" }
quests[11988] = { id = 11988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runic Keystone", description = "Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish.\n\nAt the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.", sourceObjective = "Bring 5 Runic Keystone Fragments to Torthen Deepdig at the Westfall Brigade Encampment.", progress = "Do you have enough of the fragments to reconstruct the keystone?", completion = "<Torthen works quickly to assemble the fragments you retrieved.>\n\nThis is incomplete, but it should still allow us to get most of the information from the plate.", sourceObjectiveStatus = "unverified-source-field" }
quests[11989] = { id = 11989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truce?", description = "Watch yerself, mon.\n\nDrakuru shrunk more {race} heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list.\n\nBut things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh?\n\nDrakuru know things, mon. Things that will aid you in your struggle here.\n\n<Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.>\n\nSo, what you say, mon... truce?", sourceObjective = "Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him.", progress = "Good choice, mon. You won't be livin' to regret it....", completion = "There!\n\nNow we be connected by blood, mon. A true bond we be havin'.\n\nYou lissen carefully to Drakuru, {race}. There be much to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11990] = { id = 11990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vial of Visions", description = "First things first, mon. There be some preparatory work that need doin'.\n\nNo tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch.\n\nLucky for you, I know just the thing! And the ingredients all be close by.\n\nI need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here.\n\nHurry now, mon, before dey be haulin' me away.", sourceObjective = "Drakuru at Granite Springs wants you to bring him a Crystal Vial, a Waterweed Frond, and 3 Haze Leaves.", progress = "You got da stuff, mon?", completion = "<Drakuru takes the ingredients and deftly combines them in the vial.>\n\nThis should do it, mon. Now it be time to get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[11991] = { id = 11991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subject to Interpretation", description = "A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious.\n\nMost think they be myth, but Drakuru knows better, mon!\n\nI nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!\n\nUse my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good.", sourceObjective = "Drakuru wants you to get 5 Frozen Mojo from the Drakkari Trolls at the Ruins of Drak'Zin and then use the elixir at Drakuru's Brazier there.", completion = "Ahh, yes. Ya done good, mon.\n\nI be readin' the walls just fine from here....", sourceObjectiveStatus = "unverified-source-field" }
quests[11993] = { id = 11993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runic Prophecies", description = "We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled.\n\nWe have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination.\n\nStand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!", sourceObjective = "Torthen Deepdig at the Westfall Brigade Encampment wants you to decipher the three Rune Plates.", completion = "<Torthen listens as you recount the contents of the runic plates.>\n\nBy Madoran's hammer, he's discovered a whole new titan city!\n\n'The cradle of stone and iron.'\n\n'Ulduar nestled in the storm.'\n\nWhat d'you suppose that means? Could it be where we come from, after all these years?\n\nWe have to follow him! We have to find him!", sourceObjectiveStatus = "unverified-source-field" }
quests[11995] = { id = 11995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Presence is Required at Stars' Rest", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nStars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.", sourceObjective = "Speak with the Image of Archmage Modera at Stars' Rest.", completion = "I've been expecting you, {class}. We have much work to do, you and I.", sourceObjectiveStatus = "unverified-source-field" }
quests[11996] = { id = 11996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Presence is Required at Agmar's Hammer", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nThe Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!", sourceObjective = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "What took you so long? Time waits only for Aspects, {race}.\n\nWe have much work to do, you and I.", sourceObjectiveStatus = "unverified-source-field" }
quests[11997] = { id = 11997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "The Westfall Brigade has been dispatched to the northeastern part of Grizzly Hills to secure passage for our troops. They have established a base camp to the northeast of Grizzlemaw, and to the southwest of Thor Modan.\n\nYou might recognize the brigade's leader, Captain Gryan Stoutmantle as an honored veteran of the war against the Scourge in Lordaeron. But the people of Westfall know him best for his decision to leave the battlefield and return home to take on the Defias.", sourceObjective = "Speak with Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", sourceObjectiveStatus = "unverified-source-field" }
quests[11998] = { id = 11998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Softening the Blow", description = "Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan.\n\nBrugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders.\n\nThe news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line.\n\nMan's not right in the head, but you won't find better moonshine out here.", sourceObjective = "Bring Brugar Stoneshear at the Westfall Brigade Encampment a cask of Howlin' Good Moonshine.", progress = "What's that you have there?", completion = "Let me get this straight -- a {race} I don't know brings me a cask of the finest booze in this miserable forest. Ok, then, what are you after?", sourceObjectiveStatus = "unverified-source-field" }
quests[11999] = { id = 11999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI want more information and you are going to get it for me!\n\nAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.", sourceObjective = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!", sourceObjectiveStatus = "unverified-source-field" }
quests[12000] = { id = 12000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI need more information and I hope that you will get it for me.\n\nAfter the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.", sourceObjective = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Modera at Stars' Rest.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!", sourceObjectiveStatus = "unverified-source-field" }
quests[12001] = { id = 12001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLDHunting Tarot: Lesser Beasts", description = "Staring into the card, the image blurs until you see yourself standing covered in the furs from many wolves and bears.  You can only assume this is your destiny should you invoke the tarot's power.", sourceObjective = "Collect 12 Torn Hides and then summon the Huntsman with the Hunting Tarot. The Torn Hides can only be gathered from beasts of level 5 or higher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12002] = { id = 12002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers in Battle", description = "I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down.\n\nYou seem like a brave sort, though, and you have Stoutmantle's trust.\n\nThor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.", sourceObjective = "Kill 10 Runic Battle Golems and return to Brugar Stoneshear at the Westfall Brigade Encampment.", completion = "<Brugar listens to your report.>\n\nIt sounds like things may be calming down there a bit. We'll start looking for entrances to the iron dwarves' tunnel system.", sourceObjectiveStatus = "unverified-source-field" }
quests[12003] = { id = 12003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Tunnels", description = "The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings.\n\nAs I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them.\n\nAny tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.", sourceObjective = "Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan.", progress = "I don't suppose you managed to find the tunnels, did you?", completion = "<Brugar utters a stream of foul dwarven words.>\n\nNo entrances? None?\n\nNo, of course it couldn't be that easy. Well, I suppose there's no avoiding a foray into the city proper. My boys'll never get back to their real work.", sourceObjectiveStatus = "unverified-source-field" }
quests[12004] = { id = 12004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", sourceObjective = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "Unfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get to more important business.", sourceObjectiveStatus = "unverified-source-field" }
quests[12005] = { id = 12005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", sourceObjective = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "That's alright, {class}, just put them down on the ground there in front of Agmar's throne.\n\n\n\nUnfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get on to more important business.", sourceObjectiveStatus = "unverified-source-field" }
quests[12006] = { id = 12006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge this Atrocity!", description = "These so-called mage hunters came here and destroyed our resting place.\n\nAvenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!", sourceObjective = "Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens.", progress = "Somehow I sense that you haven't quite killed enough of these defilers!", completion = "Very well, you have satisfied my request if nothing more.\n\nThank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12007] = { id = 12007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrifices Must be Made", description = "I've got it, mon!\n\nTo da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir.\n\nAgain, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.\n\nIt be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.", sourceObjective = "Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak.\n\nYou will need to collect Zim'bo's Mojo to use Drakuru's Elixir there.", progress = "You get da Eye of the Prophets, mon?", completion = "Dis be it, mon!\n\nIt be even more precious than I hoped. Dis be sure to bring mah people hope in dese dark times.\n\nNo time to waste, now. Let's be seein' where da next artifact be hidin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[12008] = { id = 12008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agmar's Hammer", description = "Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight.\n\nWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.\n\nGo now, {name}! Race the winds! East to Agmar's Hammer!", sourceObjective = "Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar.", completion = "While you have undoubtedly championed the cause of the Horde elsewhere, many more have been working towards expanding our grasp deeper into Northrend. Even now we have forces establishing bases in the frozen reaches of this desolate wasteland.\n\nWe surround the Scourge on all sides. Victory nears as our armies amass at the foot of the Wrathgate, Angrathar. Soon we will tear down the gate and breach Icecrown.\n\nBut there is much work left to be done...\n\nFirst we stop the Nerubians!", sourceObjectiveStatus = "unverified-source-field" }
quests[12009] = { id = 12009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tua'kea's Crab Traps", description = "With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me?\n\nI have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous.\n\nPlease, take this bladder. It will help you to breathe while you're down there.", sourceObjective = "Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor.", progress = "How many crabs did you manage to retrieve?", completion = "I'm a simple trapper. The world has turned upside-down all of a sudden. It doesn't make sense.\n\nI hope that you'll be able to set it right again.", sourceObjectiveStatus = "unverified-source-field" }
quests[12010] = { id = 12010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Orlond", description = "When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city.\n\nIf we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!", sourceObjective = "Locate Surveyor Orlond within Thor Modan.", completion = "A quick examination of the body reveals that the surveyor has been dead for some time. Looking through his pack, you stumble upon Orlond's handwritten notes.", sourceObjectiveStatus = "unverified-source-field" }
quests[12011] = { id = 12011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Big Watery Trouble", description = "This crab trap appears to have been destroyed by something much larger than the nearby circling sharks.\n\nPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?", sourceObjective = "Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap.", completion = "That's not the news I wanted to hear, {race}.\n\nNo, no... it's good that you told me, but I fear my old nemesis has returned to these waters.", sourceObjectiveStatus = "unverified-source-field" }
quests[12012] = { id = 12012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", sourceObjective = "Travel to a capital city and speak to the Earthen Ring Elder.", progress = "What troubles you, my child?", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[12013] = { id = 12013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End Arcanimus", description = "There is one last thing that I would have you do, {name} the {race}. I would have you destroy Arcanimus!\n\nThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!\n\nI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.\n\nYou will put an end to it now!", sourceObjective = "Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens.", progress = "Do you think me a fool? Arcanimus is still eating the souls of my brothers and sisters, {class}!", completion = "You have my deepest gratitude, {name}.\n\nIf you haven't already, you should alert your betters to the danger that the blue dragonflight has unleashed. By blowing apart the ley line anchor underneath the gardens, they threaten to destroy us all!", sourceObjectiveStatus = "unverified-source-field" }
quests[12014] = { id = 12014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady as a Rock?", description = "Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen.\n\nThe survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.'\n\nThe last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.", sourceObjective = "Retreive the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment.", progress = "What did you find?", completion = "<Brugar looks over the report.>\n\nThis isn't good at all. Even if we could excavate the tunnels behind the blockage, there's no guarantee they wouldn't collapse again. It looks like some of these areas haven't been used in generations. We'll have to give Captain Gryan the bad news.", sourceObjectiveStatus = "unverified-source-field" }
quests[12016] = { id = 12016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait", description = "I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With Food\", has returned. We must lay a trap for him, you and I.\n\nIf Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up.\n\n\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.", sourceObjective = "Obtain The Flesh of \"Two Huge Pincers\" and deliver it to Tua'kea at Moa'ki Harbor.", progress = "You return with the succulent flesh of Kili'ua?", completion = "You were able to slay Kili'ua... perhaps you'll be able to do the same to Tu'u'gwar.\n\nPerhaps not.", sourceObjectiveStatus = "unverified-source-field" }
quests[12017] = { id = 12017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat on the Hook", description = "The time has come my friend: Tu'u'gwar must be dealt with!\n\nI've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.\n\nWhatever you do, don't let Tu'u'gwar swallow you whole, {name}!", sourceObjective = "Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.", progress = "I thought I might have spotted some thrashing... is Tu'u'gwar dead?", completion = "We shall rejoice at your success, my young friend! There's blood in the water and it is our enemy's!\n\nYou have the eternal gratitude of this old fisherman, and most certainly of all the Kalu'ak once I spread the word!\n\nHere now, I insist, take something as a reward, please.", sourceObjectiveStatus = "unverified-source-field" }
quests[12018] = { id = 12018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Revenge", description = "You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. \n\nYes. Go. Kill.", sourceObjective = "Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields. Return to Lord Bevis when the task is complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[12019] = { id = 12019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Rites", description = "I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly.\n\nNow that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel.\n\nWork your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.", sourceObjective = "Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar. Use it to reach the top and help Thassarian there.", progress = "Hail, {name}.", completion = "You did well, {name}.  I was hoping to leave my sister out of all this.  Thanks to you she is alive and well.\n\nMy obligations to my king and my army have been fulfilled.  It is clear I'm not welcome among my comrades anymore.  I will have to find my own way, fighting no wars but my own and following no orders but my heart's.\n\nPerhaps we shall meet again, {class}.  Until then, take this as a token of my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[12020] = { id = 12020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", sourceObjective = "Talk to Boxey Boltspinner in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12021] = { id = 12021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter Home", description = "This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields.  Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.", sourceObjective = "Bring the letter home to Lady Alustra in the Eastern Carrion Fields.This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields. Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12022] = { id = 12022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Hey there!  You look like you can handle your brew.  But can you handle your brew mug? \n\nThe Dark Irons have come back with a vengeance to ruin our celebration.  Tossing mugs at them is the best way to stop them, but first, let's see if you can toss one at old S.T.O.U.T. here.\n\nIt's easy, pick up a complimentary sampler and take a drink.  Just make sure you're facing S.T.O.U.T.  Talk to me after you've hit him 5 times.", sourceObjective = "Use the Complimentary Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Boxey Boltspinner.", progress = "Toss one back, then toss one forward.  S.T.O.U.T. can take the abuse, it's why I built him.", completion = "Do you know what that was?  Gnomish engineering at its finest!  S.T.O.U.T. took the abuse like a champ!\n\nI think you're ready now to take on the Dark Irons if they show up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[12024] = { id = 12024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recording the Fallen", description = "Thank you for coming {name}.  We haven't received any word from Wintergarde Keep.  I'm sure they're still battling the Scourge, but I can believe they left us alone to this slaughter.  \n\nWe need to gather the names of the dead so that we can notify their families.  When the Alliance Military brought us here, we all filled out Settlement Documentation and were required to keep it on our persons.  \n\nGo sift through the corpses and bring me any Documents that you find so that I can start a list of the names.", sourceObjective = "Search the skeletons in the Carrion Fields for Alliance Settlement Documents.", sourceObjectiveStatus = "unverified-source-field" }
quests[12025] = { id = 12025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarlet Among Us", description = "It's good to see that you were not ravaged by the Scourge as well.  Perhaps you'd be willing to lend a hand.  \n\nThe Scarlet Crusade has taken up a post to the north with the obvious intent of battling the Scourge.  The thing that bothers me is that they were building before we were attacked - they must have known something.  \n\nI need to know if one of our Villagers was involved.  Search for evidence on those of us that were brought back as ghouls.  If you find anything, bring it to me.", sourceObjective = "Search for evidence of the Scarlet Crusade on the freshly risen Carrion Ghouls in the Eastern Carrion Fields. Return to Lady Alustra with anything you find.", sourceObjectiveStatus = "unverified-source-field" }
quests[12026] = { id = 12026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language.\n\nThe only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries.\n\nThe back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.", sourceObjective = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah.", progress = "What's that you have there?", completion = "Who is this Brann Bronzebeard? The iron dwarves found no reason to treat with him, but I have no idea why we'd be interested in his writings.", sourceObjectiveStatus = "unverified-source-field" }
quests[12027] = { id = 12027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Floppy's Perilous Adventure", description = "Excuse me, <Mister/Ma'am>, do you know the way back to the soldiers' camp?\n\nMr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do.\n\nSo Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower.\n\nThe wolves went away, but we're still lost.\n\nI asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?", sourceObjective = "Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.", completion = "Thank goodness you found Emmy! When she left without me, I was worried she'd get lost.\n\nI'm glad to see Mr. Floppy's back safe and sound, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[12028] = { id = 12028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Insight", description = "{race}, we have not heard from our people at Indu'le Village since the ground shook and was torn apart!\n\nHave you ever been upon a vision quest? You've bested Loguhn, so you must be capable.\n\nI will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le.\n\nAs your spirit soars, I will be able to look through your eyes.", sourceObjective = "Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight.", progress = "What do you think?", completion = "Ghosts and gibbering madness? This cannot be!\n\nWe must seek further guidance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12029] = { id = 12029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seared Scourge", description = "<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again.\n\nPoppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice.\n\nSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit.\n\nHow 'bout ya take shome o my grog here and put them bashtards outta their misery?", sourceObjective = "Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon.", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...<hic>.", sourceObjectiveStatus = "unverified-source-field" }
quests[12030] = { id = 12030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Mana'loa", description = "My people....\n\n<The mystic is on the verge of breaking down.>\n\nWhile your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. {name}, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.\n\nThe elder must want to help. Seek him in the northwest corner of the village.", sourceObjective = "Speak with the statue, Elder Mana'loa, at Indu'le Village.", completion = "I've been expecting you, {race}. I saw your spirit fly by and sensed the mystic watching behind your eyes.\n\nYour fate and that of the Kalu'ak are now tied together.", sourceObjectiveStatus = "unverified-source-field" }
quests[12031] = { id = 12031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for the Lingering", description = "The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.\n\nThe souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic.\n\nThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.\n\n{name}, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.", sourceObjective = "Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village.", progress = "<Elder Mana'loa looks through you, sensing that you have not yet completed his task.>", completion = "Not the most pleasant task, but necessary and merciful.\n\nAnd now there is something else that you are destined to do for the Kalu'ak.", sourceObjectiveStatus = "unverified-source-field" }
quests[12032] = { id = 12032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conversing With the Depths", description = "The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether.\n\nOff the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests.\n\nCommune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr.\n\nShould you survive, return to the mystic.", sourceObjective = "Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs.\n\nShould you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.", progress = "{name}, you have returned!", completion = "You spoke with Oacha'noa?!\n\nIf it is her will that we stand with your people then so be it. Elder Ko'nani will accept this as our destiny, for weal or woe.\n\nMy people believe that all souls are one with the magic of the world. We must oppose the blue dragon attempts to control the magic or we are all doomed!\n\nI never thought that a {race} would be the champion of the Kalu'ak, but you have proven me wrong. On behalf of my people, I give you thanks, {name}.\n\nMay the gods smile upon you and keep you safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12033] = { id = 12033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message from the West", description = "<Torvus shakes your hand, giving you a letter in the process.>\n\n<Torvus speaks under his breath.>\n\nJust play along, {name}.\n\nIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!\n\n<Torvus speaks under his breath.>\n\nRead it and then destroy it in the fire pot next to me.", sourceObjective = "Read the Letter from Saurfang and then destroy it.\n\nSpeak to Messenger Torvus once you have completed this task.", progress = "We will crush the Scourge!", completion = "<Torvus nods at you.>\n\nSo we are understood? I will return to my lord and tell him that you have accepted.", sourceObjectiveStatus = "unverified-source-field" }
quests[12034] = { id = 12034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory Nears...", description = "There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist.\n\nWe will destroy the Anub'ar and close off the Pit of Narjun.\n\nReport to Senior Sergeant Juktok for your mission orders.", sourceObjective = "Speak to Senior Sergeant Juktok at Agmar's Hammer.", completion = "By land and by air, that's how we will end the Anub'ar threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12035] = { id = 12035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repurposed Technology", description = "Ok, I've got it!  The rewiring is a little complicated, but nothing a clever {class} like you can't handle.\n\nTake my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, {name}.  Before long there won't be anything left to save.", sourceObjective = "Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.", progress = "You done yet, {name}?", completion = "Nice job!  I finally feel useful again... and that's sayin' something.", sourceObjectiveStatus = "unverified-source-field" }
quests[12036] = { id = 12036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Depths of Azjol-Nerub", description = "The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.\n\nI need eyes on the ground, {name}. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.", sourceObjective = "Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer.", progress = "What's taking so long?", completion = "That damned sinkhole must be directly connected to Azjol-Nerub. This is worse than I thought.\n\n<Juktok pauses to think for a moment.>\n\nSeek and destroy... That'll be the next course of action.", sourceObjectiveStatus = "unverified-source-field" }
quests[12037] = { id = 12037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search and Rescue", description = "Orcs... they just don't lissen <hic>. Know what I mean, {race}?\n\nKurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand?\n\nNot her though... she goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself <hic>.\n\nSo whatdya say, pal?", sourceObjective = "Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel.", completion = "I knew it!\n\nEven my going missing wasn't enough to get those spineless weasels to come in here after me.\n\nWell, they sent you. I suppose that's something....\n\nHere, take this. I'd rather it go to you than to those dimwits back at the camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[12038] = { id = 12038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seared Scourge", description = "Whatcha waitin' fer, {class}? Them shcourged trolls ain't gunna kill themselves!\n\nYou know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.", sourceObjective = "Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls.", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...hic.", sourceObjectiveStatus = "unverified-source-field" }
quests[12039] = { id = 12039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Blood of Yogg-Saron", description = "Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal \"breathe.\"\n\nOnly ones who knew anything about it were the tuskarr. They called it the \"Black Blood of Yogg-Saron\" and told me to keep my distance.\n\nThere's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?", sourceObjective = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples.", progress = "What's life without risks?", completion = "It's so light... As if it weighs nothing at all! I'll need time to analyze the metal and see if I can do anything with it! Tests! I need to run tests!\n\nI'll keep in contact, {name}. If anything comes of this, you'll be the first to know.", sourceObjectiveStatus = "unverified-source-field" }
quests[12040] = { id = 12040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Enemy in Arthas", description = "We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death.\n\nIn Arthas we both have an enemy...\n\nJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!", sourceObjective = "Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords.", progress = "The Azjol Empire will rise again!", completion = "There are thousands more and they spill out from every dark crevice in Northrend. Alone you stand no chance, but together... Maybe...", sourceObjectiveStatus = "unverified-source-field" }
quests[12041] = { id = 12041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Empire", description = "You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde.\n\nTake this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all.\n\nFarewell, {race}.", sourceObjective = "Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.", progress = "What have you got there?", completion = "<Overlord Agmar looks over the document.>\n\nIs this what I think it is? With the information contained within these pages we will CRUSH the Anub'ar assault!\n\nYou have done well to bring this document to me, {name}. Perhaps you will be allowed to watch or even participate in the final battle at Angrathar! LOK'TAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[12042] = { id = 12042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Ancients", description = "Secrets of da ages, be revealed to me now!\n\n<Drakuru peers through the Eye of the Prophets.>\n\nAhh, great be mah destiny, {name}. You be lucky ta know me....\n\nThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!\n\nYou gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees.\n\nHurry, mon, before someone else be findin' it!", sourceObjective = "Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients.", completion = "This unfortunate goblin must have unearthed the Heart of the Ancients during his excavations in the region.\n\nIt's doubtless that he had no clue as to its nature.\n\nYou determine that it must have been overlooked in the chaos sweeping through the area.", sourceObjectiveStatus = "unverified-source-field" }
quests[12043] = { id = 12043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nozzlerust Defense", description = "You, {class}!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?", sourceObjective = "Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest. Return to Narf at Nozzlerust Post when the task is complete.", progress = "Huh?  Who are you?  What do you want?", completion = "Oh!  Yeah, the undead.  Here's your coin, bugger off.", sourceObjectiveStatus = "unverified-source-field" }
quests[12044] = { id = 12044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process.\n\nGo lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting.", sourceObjective = "Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post.", progress = "Did you get the ore?  My carrier will be back shortly - we need to get this shipment out while the fight's still going!", completion = "Hah!  That's quite a load!  Your back feeling alright?", sourceObjectiveStatus = "unverified-source-field" }
quests[12045] = { id = 12045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaved Ice", description = "I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands.\n\nYou get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich.\n\nI actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya?", sourceObjective = "Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post.", progress = "Do you have the shards?  I'm almost finished with the main refrigeration unit.", completion = "Excellent!  They're even sharper than I expected them to be.  I'll pack them in the snow until the bomb is ready.\n\nLet's see... what next...", sourceObjectiveStatus = "unverified-source-field" }
quests[12046] = { id = 12046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Packaging", description = "I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.  \n\nWhat we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find.", sourceObjective = "Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post. Once you've located the hides, return them to Zivlix.", progress = "How goes the hunt?  Do you have my hides?", completion = "Good... good... these should do fine.  The shrapnel bombs are almost finished. \n\nWait... what happened to my ice shards?  Narf told me shards from those elementals should be enchanted, but they're melting just like the ones hanging from Narf's grumpy chin!", sourceObjectiveStatus = "unverified-source-field" }
quests[12047] = { id = 12047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something That Doesn't Melt", description = "No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel.\n\nI know! I'm brilliant. Bone splinters.\n\nThere are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.", sourceObjective = "Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks.", progress = "Were there any splinters to be found?", completion = "Excellent!  That should be the last thing I need to test out the new bombs.  Just a moment and I'll try this out!", sourceObjectiveStatus = "unverified-source-field" }
quests[12048] = { id = 12048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge Armaments", description = "I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend!\n\nPerhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created.\n\nIcemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore.\n\nYou'll find Icemist to the west.", sourceObjective = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.", progress = "<Borus throws his tools down.>\n\nThese are useless!", completion = "These are in excellent condition, {name}. I'll get to work right away. If anything comes of this, you will be the first to know!", sourceObjectiveStatus = "unverified-source-field" }
quests[12049] = { id = 12049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Swallow", description = "Those troops are sure to be needin' a hefty supply of food in their bellies.\n\nI'll let you in on a little secret that a squeamish {race} like you would never know... those jormungar worms taste just like chicken.\n\nGo provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.", sourceObjective = "Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink.", progress = "Did ya get it all?  You certainly stink of it.", completion = "Ha ha!  One of those meat slabs landed clear over here!  Nice work there!", sourceObjectiveStatus = "unverified-source-field" }
quests[12050] = { id = 12050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Hack", description = "Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the harpies are nesting in to the north look much more fit for structures.\n\nTake this.  When you get to the harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The harpies are sure to disagree with you chopping down their homes - just deal with them as necessary.\n\nHop to it!", sourceObjective = "Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North. Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post.\n\nShould you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one.", progress = "Where's that carrier?  Hope the Jormungar didn't get him.  He was carrying a good sized load that time.", completion = "If a tree falls in the forest, and you can't hear it through the saw blade, does it really make a sound?", sourceObjectiveStatus = "unverified-source-field" }
quests[12051] = { id = 12051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustling Some Feathers", description = "Those harpies have slowed our profits long enough!  Kill them all.", sourceObjective = "Kill 20 Harpies Northwest of Nozzlerust Post for Narf at Nozzlerust Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[12052] = { id = 12052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harp on This!", description = "{class}, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.\n\n Those harpies have slowed our profits long enough! Kill them all.", sourceObjective = "Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete.\n\nShould you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post.", progress = "I remember you. You're not dead, so those harpy wenches better be.", completion = "That should make those uglies think twice.  Here... take your reward and get away with ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[12053] = { id = 12053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Horde", description = "The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village.\n\nYou will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down!\n\nLet the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!", sourceObjective = "Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers.\n\nReturn the Warsong Battle Standard when you are finished.", progress = "It is a challenge, {name}!", completion = "We have crushed them by land! Soon we will crush them by air!", sourceObjectiveStatus = "unverified-source-field" }
